{
  "name": "多维数据维度选择器",
  "name_en": "Multi-Dimension Selector",
  "manufacturer": "",
  "description": "这是一个用于实验数据可视化与分析界面的软件组件，不是物理仪器。它通过列表框或下拉框帮助用户从数据集中选择一个或多个维度、坐标轴或因变量，常用于实验测量数据的浏览、绘图和流程图节点配置。",
  "description_en": "This is a software UI component rather than a physical instrument. It helps users select one or more dimensions, axes, or dependent variables from a dataset using list or combo-box based controls, typically for laboratory data browsing, plotting, and flowchart node configuration.",
  "tag_hints": [
    "data dimension selection",
    "lab data visualization",
    "plot axis selection",
    "dataset browsing",
    "flowchart node UI",
    "multi-select list widget"
  ],
  "actions": [
    {
      "action_name": "auto-connectNode",
      "description": "连接到数据节点，并根据节点中的数据维度更新可选项。",
      "description_en": "Connect to a data node and update the available dimension options from the node data."
    },
    {
      "action_name": "auto-emitSelection",
      "description": "发出当前维度选择结果。",
      "description_en": "Emit the current dimension selection."
    },
    {
      "action_name": "auto-getSelected",
      "description": "获取当前选中的数据维度。",
      "description_en": "Get the currently selected data dimensions."
    },
    {
      "action_name": "auto-setDimensions",
      "description": "设置可供选择的数据维度列表。",
      "description_en": "Set the list of available data dimensions."
    },
    {
      "action_name": "auto-setSelected",
      "description": "设置当前选中的数据维度。",
      "description_en": "Set the currently selected data dimensions."
    },
    {
      "action_name": "auto-spinValueChanged",
      "description": "发出监视或刷新间隔数值变化信号。",
      "description_en": "Emit a monitor or refresh interval value-change signal."
    },
    {
      "action_name": "auto-setDefaultStyle",
      "description": "应用默认界面样式。",
      "description_en": "Apply the default interface style."
    },
    {
      "action_name": "auto-addNodeWidget",
      "description": "添加一个节点控制部件。",
      "description_en": "Add a node control widget."
    },
    {
      "action_name": "auto-addNodeWidgetsFromFlowchart",
      "description": "从流程图中添加节点控制部件。",
      "description_en": "Add node control widgets from a flowchart."
    },
    {
      "action_name": "auto-closeEvent",
      "description": "处理窗口关闭事件。",
      "description_en": "Handle a window close event."
    },
    {
      "action_name": "auto-loadSnapshot",
      "description": "加载已保存的快照或界面状态。",
      "description_en": "Load a saved snapshot or interface state."
    },
    {
      "action_name": "auto-restart_widget",
      "description": "重启或重建该界面部件。",
      "description_en": "Restart or rebuild the widget."
    },
    {
      "action_name": "auto-signalDimensionSelection",
      "description": "发出维度选择变化信号。",
      "description_en": "Emit a dimension-selection change signal."
    }
  ]
}

